python3 - <<'PY'
from datetime import datetime, timedelta, time
from pathlib import Path

people = ('alice', 'bob', 'carol')
calendars = {}
for person in people:
    events = []
    lines = Path(f'/app/{person}_calendar.ics').read_text().splitlines()
    for i, line in enumerate(lines):
        if line == 'BEGIN:VEVENT':
            start = datetime.strptime(lines[i+2].split(':', 1)[1], '%Y%m%dT%H%M%SZ')
            end = datetime.strptime(lines[i+3].split(':', 1)[1], '%Y%m%dT%H%M%SZ')
            events.append((start, end))
    calendars[person] = events

def overlap(start, end, events):
    return any(start < e and end > s for s, e in events)

def valid(start):
    end = start + timedelta(hours=1)
    if start.weekday() >= 5 or start.time() < time(9) or end.time() > time(18):
        return False
    # Alice: 09:00-14:00 hard window.
    if start.time() < time(9) or end.time() > time(14):
        return False
    # Bob: no meetings before 10:00; Tue/Thu departure at 16:30.
    if start.time() < time(10):
        return False
    if start.weekday() in (1, 3) and end.time() > time(16, 30):
        return False
    # Carol: 09:00-17:00 and 12:00-12:30 lunch.
    if start.time() < time(9) or end.time() > time(17):
        return False
    if start < start.replace(hour=12, minute=30) and end > start.replace(hour=12):
        return False
    return all(not overlap(start, end, calendars[p]) for p in people)

slots = []
for day in range(15, 20):
    base = datetime(2024, 1, day, 9)
    for minute in range(9 * 60, 18 * 60 - 60 + 1):
        candidate = datetime(2024, 1, day) + timedelta(minutes=minute)
        if valid(candidate):
            slots.append(candidate)
print('first valid:', slots[0].strftime('%Y-%m-%d %H:%M'))
print('valid slot count:', len(slots))
print('Monday valid slots:', sum(s.weekday() == 0 for s in slots))
assert slots[0] == datetime(2024, 1, 17, 11)
assert slots[0] + timedelta(hours=1) == datetime(2024, 1, 17, 12)
